using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change: "Discriminator" renamed to "$type" in EF Core 9.
            // Preserve old property name for backward compat with existing documents.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change: id format changed from "EntityType|Key" to just "Key".
            // Preserve old format for existing documents.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();

            // Breaking change: HasIndex is no longer supported by the Cosmos provider.
            // Removed: entity.HasIndex(b => b.Name);
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // Kept for raw SQL queries: SELECT * FROM c WHERE c.Discriminator = 'Blog'
